/**
 * CONCEPT 05 - Christmas at Home / A Cozy Evening
 * Original, asset-free 2D Canvas animation. Duration: 25 seconds, three scenes.
 * Reference: 3840 x 2160, 16:9, 60 fps; proportionally scalable to FHD and 2K.
 * Time is supplied in SECONDS. No DOM, external libraries, humans or animals.
 * Static gradient backgrounds; no glow, bloom, shadows or 3D objects.
 * Each concept is standalone. Load one file per renderer instance.
 * Host encoder target/minimum: 100,000,000 bits per second (100 Mbps).
 * Canvas draws frames only. The host renderer must enforce the export bitrate.
 */
function draw(ctx, time, width, height) {

  if (!ctx || !Number.isFinite(time) || !(width > 0) || !(height > 0)) return;
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, minSide / 1080);
  const localT = sceneProgress * sceneDuration;
  const TAU = Math.PI * 2;
  const cycle = TAU * loopT / duration;
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { v = clamp(v); return v * v * v * (v * (v * 6 - 15) + 10); };
  const progress = (a, b) => ease((localT - a) / (b - a));
  const mix = (a, b, v) => a + (b - a) * v;
  const rgba = (r, g, b, a) => 'rgba(' + r + ',' + g + ',' + b + ',' + clamp(a) + ')';
  function colorMix(a, b, v) {
    const aa = parseInt(a.slice(1), 16), bb = parseInt(b.slice(1), 16);
    return '#' + [16, 8, 0].map(s => Math.round(mix((aa >> s) & 255, (bb >> s) & 255, clamp(v))).toString(16).padStart(2, '0')).join('');
  }
  function rr(x, y, w, h, r, fill, stroke, lw = 2) {
    if (!(w > 0 && h > 0)) return;
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function circle(x, y, r, fill, stroke, lw = 2) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, stroke, lw = 2) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke();
  }
  function polygon(points, fill, stroke, lw = 2) {
    ctx.beginPath(); points.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function star(x, y, r, fill, stroke, angle = -Math.PI / 2, points = 5) {
    const p = [];
    for (let i = 0; i < points * 2; i++) {
      const a = angle + i * Math.PI / points, d = i % 2 ? r * 0.46 : r;
      p.push([x + Math.cos(a) * d, y + Math.sin(a) * d]);
    }
    polygon(p, fill, stroke, 2.2);
  }
  function snowflake(x, y, r, stroke, angle = 0, lw = 2) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = i * Math.PI / 3, c = Math.cos(a), s = Math.sin(a);
      ctx.moveTo(0, 0); ctx.lineTo(r * c, r * s);
      for (const side of [-1, 1]) {
        const b = a + side * Math.PI / 3;
        ctx.moveTo(r * 0.56 * c, r * 0.56 * s);
        ctx.lineTo(r * 0.56 * c + Math.cos(b) * r * 0.23, r * 0.56 * s + Math.sin(b) * r * 0.23);
      }
    }
    ctx.stroke(); ctx.restore();
  }
  function text(str, x, y, size, color, maxW, align = 'left', weight = 500) {
    ctx.save(); ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.font = weight + ' ' + size + 'px sans-serif';
    const measured = ctx.measureText(str).width;
    if (maxW && measured > maxW) { size *= maxW / measured; ctx.font = weight + ' ' + size + 'px sans-serif'; }
    ctx.fillStyle = color; ctx.fillText(str, x, y); ctx.restore();
  }
  function tracked(str, x, y, size, spacing, color, center = false) {
    ctx.save(); ctx.font = '600 ' + size + 'px sans-serif'; ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
    const widths = Array.from(str).map(ch => ctx.measureText(ch).width);
    const total = widths.reduce((a, b) => a + b, 0) + spacing * Math.max(0, widths.length - 1);
    let cursor = center ? x - total / 2 : x; ctx.fillStyle = color;
    Array.from(str).forEach((ch, i) => { ctx.fillText(ch, cursor, y); cursor += widths[i] + spacing; }); ctx.restore();
  }
  function group(x, y, rotation, opacity, fn) {
    if (opacity <= 0) return;
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotation); ctx.globalAlpha *= clamp(opacity); fn(); ctx.restore();
  }
  function bow(x, y, size, fill, stroke, reveal = 1) {
    if (reveal <= 0) return;
    ctx.save(); ctx.translate(x, y); ctx.globalAlpha *= clamp(reveal);
    for (const side of [-1, 1]) {
      ctx.save(); ctx.scale(side, 1);
      ctx.beginPath(); ctx.moveTo(0, 0);
      ctx.bezierCurveTo(size * 0.17, -size * 0.47, size * 0.91, -size * 0.87, size, -size * 0.37);
      ctx.bezierCurveTo(size * 1.06, size * 0.04, size * 0.43, size * 0.17, 0, 0); ctx.closePath();
      ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = stroke; ctx.lineWidth = 2.4; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(size * 0.13, -size * 0.05); ctx.quadraticCurveTo(size * 0.46, -size * 0.25, size * 0.75, -size * 0.31);
      ctx.strokeStyle = stroke; ctx.lineWidth = 1.6; ctx.stroke(); ctx.restore();
    }
    rr(-size * 0.14, -size * 0.17, size * 0.28, size * 0.31, size * 0.08, fill, stroke, 2.3);
    ctx.restore();
  }
  function ribbonWipe(fill, edge) {
    const d = 0.56;
    let x, w;
    if (localT < d) { x = mix(-8, 1928, ease(localT / d)); w = 1936 - x; }
    else if (localT > sceneDuration - d) { x = -8; w = mix(0, 1936, ease((localT - (sceneDuration - d)) / d)); }
    else return;
    ctx.save(); ctx.fillStyle = fill; ctx.fillRect(x, -12, w, 1104);
    // This opaque, full-frame ribbon hides scene handoffs; it is not a background animation.
    ctx.beginPath(); ctx.rect(x, -12, w, 1104); ctx.clip();
    for (let i = 0; i < 3; i++) line(0, 488 + i * 51, 1920, 488 + i * 51, edge, i === 1 ? 2.2 : 1.1);
    snowflake(960, 540, 25, edge, 0, 2.1);
    ctx.restore();
  }
  ctx.save();
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0; ctx.shadowColor = 'transparent';
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]); ctx.lineDashOffset = 0; ctx.lineCap = 'round'; ctx.lineJoin = 'round';

  const C={ink:'#61474b',cream:'#f7ecdc',paper:'#efe0cb',gold:'#d5b482',red:'#ad6b76',sage:'#829b8a',muted:'#886b70',night:'#5b6b80',dark:'#51434a'};
  const bg=ctx.createLinearGradient(0,0,width,height);
  bg.addColorStop(0,'#e3d0bf');bg.addColorStop(0.54,'#ceb3a8');bg.addColorStop(1,'#bd999d');
  ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);
  ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);

  // This wall, floor, rug, border and decorative etching never move or change colour.
  line(130,75,1790,75,'#b18c8d',1.2);line(130,1007,1790,1007,'#b18c8d',1.2);
  line(130,1033,220,1033,C.ink,2);line(1700,1033,1790,1033,C.ink,2);
  line(170,851,1750,851,'#9f7c80',2);
  rr(290,877,1340,40,20,'#c29da0',null);
  for(let i=0;i<3;i++)line(340,888+i*9,1580,888+i*9,'#d6b7b0',1.1);
  snowflake(1740,165,26,'#a57c83',Math.PI/6,1.4);
  snowflake(154,927,17,'#ad8589',0,1.3);
  tracked('A CHRISTMAS AT HOME',145,125,15,3.9,C.ink);
  text('Small details. A little warmth. A place to belong.',192,976,18,C.ink,1320);
  snowflake(1768,963,12,C.ink,0,1.6);

  function arch(x,y,w,h,fill,stroke,lw=2.6){
    const r=w/2;
    ctx.beginPath();ctx.moveTo(x,y+h);ctx.lineTo(x,y+r);
    ctx.arc(x+r,y+r,r,Math.PI,0,false);ctx.lineTo(x+w,y+h);ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function candle(x,base,h,w=24,id=0){
    group(x,base,0,1,()=>{
      rr(-w/2,-h,w,h,4,C.cream,C.ink,1.9);
      line(-w*.28,-h+11,w*.28,-h+11,C.gold,1.3);
      line(0,-h-1,0,-h-12,C.ink,1.6);
      const lean=1.8*Math.sin(cycle*2+id);
      ctx.beginPath();ctx.moveTo(0,-h-12);
      ctx.bezierCurveTo(-12,-h-19,-7+lean,-h-29,lean,-h-35);
      ctx.bezierCurveTo(10+lean,-h-23,12,-h-17,0,-h-12);ctx.closePath();
      ctx.fillStyle=C.gold;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=1.6;ctx.stroke();
    });
  }
  function flame(x,base,h,w,id,color){
    const lean=3.1*Math.sin(cycle*2+id),height=h*(1+0.035*Math.sin(cycle*3+id));
    ctx.beginPath();ctx.moveTo(x-w/2,base);
    ctx.bezierCurveTo(x-w*.68,base-height*.30,x-w*.21+lean,base-height*.70,x+lean,base-height);
    ctx.bezierCurveTo(x+w*.20+lean,base-height*.77,x+w*.75,base-height*.30,x+w/2,base);
    ctx.quadraticCurveTo(x,base+w*.20,x-w/2,base);ctx.closePath();
    ctx.fillStyle=color;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=1.8;ctx.stroke();
  }
  function stocking(x,y,dir,id){
    group(x,y,0.024*Math.sin(cycle*1.5+id),1,()=>{
      line(0,0,0,9,C.ink,1.6);circle(0,13,5,null,C.ink,1.7);
      ctx.save();ctx.scale(dir,1);
      ctx.beginPath();ctx.moveTo(-23,22);ctx.lineTo(23,22);ctx.lineTo(23,79);
      ctx.bezierCurveTo(29,80,43,80,45,96);ctx.bezierCurveTo(48,118,20,127,5,121);
      ctx.bezierCurveTo(-13,116,-23,108,-23,91);ctx.closePath();
      ctx.fillStyle=id%2?C.sage:C.red;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=2.3;ctx.stroke();
      rr(-28,18,56,25,5,C.cream,C.ink,2.1);snowflake(0,67,12,C.cream,0,1.6);
      line(-12,99,8,107,C.gold,1.7);ctx.restore();
    });
  }
  function smallCard(x,base,w,h,word='JOY'){
    group(x,base,0,1,()=>{
      rr(-w/2,-h,w,h,6,C.cream,C.ink,2.2);
      rr(-w/2+8,-h+8,w-16,h-16,3,null,C.gold,1.2);
      star(0,-h*0.60,Math.min(w,h)*0.18,C.gold,C.ink,-Math.PI/2,5);
      text(word,0,-h*0.20,Math.min(17,w*0.16),C.ink,w-22,'center',600);
    });
  }
  function fireplace(x,base,w,h,arrival=1){
    const p=ease(arrival);
    group(x,base+(1-p)*20,0,p,()=>{
      const stone=ctx.createLinearGradient(-w/2,-h,w/2,0);
      stone.addColorStop(0,'#eedfc9');stone.addColorStop(1,'#e1cbb5');
      rr(-w/2,-h,w,h-9,9,stone,C.ink,3);
      arch(-w*.25,-h*.72,w*.50,h*.65,C.dark,C.ink,2.8);
      const f=Math.min(w/520,h/330);
      group(0,-h*.07-8,0,1,()=>{
        ctx.scale(f,f);
        flame(-57,-23,73,35,1,'#c88468');
        flame(57,-23,79,35,2.4,'#c88468');
        flame(0,-23,111,51,0,C.gold);
        flame(0,-21,61,22,0.7,'#e9cf9a');
        rr(-94,-19,89,17,6,'#997461',C.ink,1.7);rr(6,-19,89,17,6,'#997461',C.ink,1.7);
        line(-81,-11,-18,-11,'#ceb193',1.2);line(19,-11,82,-11,'#ceb193',1.2);
      });
      // The side piers leave a clear corridor around the moving stockings.
      for(const side of [-1,1]){
        for(let i=0;i<3;i++)line(side*(w*.335+i*9),-h*.45,side*(w*.335+i*9),-42,'#bea18d',1.1);
      }
      rr(-w/2-26,-h-20,w+52,32,6,C.cream,C.ink,2.8);
      line(-w/2,-h+28,w/2,-h+28,'#bda18b',1.3);
      rr(-w/2-29,-21,w+58,21,6,C.cream,C.ink,2.7);
      stocking(-w*.39,-h+6,1,0);stocking(w*.39,-h+6,-1,1.8);
      candle(-w*.35,-h-20,71,23,1);
      candle(-w*.275,-h-20,93,23,2.1);
      smallCard(w*.35,-h-20,100,96,'NOEL');
    });
  }
  function wallWindow(x,y,w,h){
    // Static winter illustration, including every snow mark outside the window.
    rr(x,y,w,h,13,C.cream,C.ink,2.8);rr(x+12,y+12,w-24,h-24,5,C.night,C.ink,1.6);
    circle(x+w*.75,y+h*.29,17,'#e5ddcf');
    for(const p of [[.18,.19],[.35,.36],[.59,.20],[.81,.67],[.24,.72],[.66,.78],[.46,.82],[.16,.48]])circle(x+w*p[0],y+h*p[1],2.1,'#d6dce0');
    line(x+w/2,y+12,x+w/2,y+h-12,C.cream,6);line(x+12,y+h/2,x+w-12,y+h/2,C.cream,6);
    rr(x-10,y+h-5,w+20,15,4,C.cream,C.ink,2.1);
    line(x+14,y+19,x+w-14,y+19,C.gold,1.6);
  }
  function chair(x,base,arrival=1){
    const p=ease(arrival);
    group(x,base+(1-p)*18,0,p,()=>{
      rr(-120,-217,240,169,30,C.sage,C.ink,2.7);
      rr(-96,-190,192,105,22,'#a9b9a3',C.ink,1.9);
      rr(-71,-173,142,83,12,C.cream,C.ink,1.8);
      for(let i=-1;i<=1;i++)snowflake(i*40,-133,10,C.red,0,1.3);
      rr(-123,-84,246,65,17,C.sage,C.ink,2.7);
      rr(-144,-149,43,128,16,C.sage,C.ink,2.5);rr(101,-149,43,128,16,C.sage,C.ink,2.5);
      rr(-107,-23,22,23,3,C.ink,null);rr(85,-23,22,23,3,C.ink,null);
      line(-98,-45,98,-45,'#bac6b1',1.5);
    });
  }
  function clock(x,y,r){
    circle(x,y,r,C.cream,C.ink,2.6);circle(x,y,r-8,null,C.gold,1.3);
    for(let i=0;i<12;i++){
      const a=i*TAU/12-Math.PI/2;
      line(x+Math.cos(a)*r*.77,y+Math.sin(a)*r*.77,x+Math.cos(a)*r*.86,y+Math.sin(a)*r*.86,C.ink,1.5);
    }
    const hour=(10+10/60+loopT/3600)*TAU/12-Math.PI/2;
    const minute=(10+loopT/60)*TAU/60-Math.PI/2;
    const second=loopT*TAU/60-Math.PI/2;
    line(x,y,x+Math.cos(hour)*r*.44,y+Math.sin(hour)*r*.44,C.ink,4);
    line(x,y,x+Math.cos(minute)*r*.65,y+Math.sin(minute)*r*.65,C.ink,2.8);
    line(x-Math.cos(second)*r*.14,y-Math.sin(second)*r*.14,x+Math.cos(second)*r*.72,y+Math.sin(second)*r*.72,C.red,1.3);
    circle(x,y,4,C.ink);
  }
  function tree(x,base,s){
    group(x,base,0,1,()=>{
      ctx.scale(s,s);rr(-17,-46,34,46,3,C.paper,C.ink,2.5);
      const fill=ctx.createLinearGradient(-180,-430,180,0);fill.addColorStop(0,'#a9b9a3');fill.addColorStop(1,'#839d8a');
      polygon([[0,-450],[82,-330],[57,-330],[151,-200],[112,-200],[224,-30],[-224,-30],[-112,-200],[-151,-200],[-57,-330],[-82,-330]],fill,C.ink,3);
      star(0,-481,31,C.gold,C.ink,-Math.PI/2,5);
      for(const row of [[-322,59],[-203,116],[-94,173]]){
        ctx.beginPath();ctx.moveTo(-row[1],row[0]);ctx.quadraticCurveTo(0,row[0]+48,row[1],row[0]);ctx.strokeStyle=C.cream;ctx.lineWidth=2.6;ctx.stroke();
      }
      for(const p of [[0,-362],[-47,-265],[47,-265],[0,-224],[-94,-147],[94,-147],[-39,-97],[39,-97],[-147,-64],[147,-64]])circle(p[0],p[1],8.4,C.red,C.ink,1.8);
      rr(-58,-4,116,4,2,C.paper,C.ink,2.1);
    });
  }
  function gift(x,base,w,h,fill=C.red){
    group(x,base,0,1,()=>{
      rr(-w/2,-h,w,h,5,fill,C.ink,2.1);
      for(const px of [-.28,.28])for(const py of [-.72,-.3])star(px*w,py*h,Math.min(w,h)*.035,C.cream,null,-Math.PI/2,4);
      rr(-w*.06,-h,w*.12,h,0,C.gold,null);rr(-w/2,-h*.48,w,h*.11,0,C.gold,null);
      rr(-w/2-5,-h-11,w+10,21,4,fill,C.ink,2);rr(-w*.06,-h-10,w*.12,19,0,C.gold,null);
      bow(0,-h-10,w*.19,C.gold,C.ink);
    });
  }
  function ornament(x,anchorY,drop,r,id){
    group(x,anchorY,0.025*Math.sin(cycle*1.5+id),1,()=>{
      line(0,0,0,drop-r-11,C.ink,1.5);rr(-r*.18,drop-r-11,r*.36,12,3,C.gold,C.ink,1.8);
      circle(0,drop,r,C.sage,C.ink,2.3);snowflake(0,drop,r*.52,C.cream,0,1.7);
    });
  }

  if(currentScene===0){
    text('Christmas feels like home.',145,215,65,C.ink,1470,'left',600);
    text('Thoughtful details for a beautifully quiet evening.',149,260,21,C.muted,1450);
    wallWindow(240,349,300,220);
    chair(390,850,progress(.12,1.05));
    fireplace(960,850,520,330,progress(.28,1.22));
    clock(960,389,58);
    group(1560,850,0,progress(.48,1.4),()=>tree(0,0,.83));
    gift(1314,850,70,82,C.red);
  }else if(currentScene===1){
    text('Little details. Lasting warmth.',145,215,61,C.ink,1490,'left',600);
    text('A few familiar things, beautifully brought together.',149,260,21,C.muted,1450);
    text('A place to',191,386,43,C.ink,455,'left',600);
    text('feel at home.',191,440,43,C.ink,455,'left',600);
    tracked('THE CHRISTMAS DETAILS',195,484,11,2.2,C.muted);
    line(320,527,257,553,C.ink,1.4);line(320,527,383,553,C.ink,1.4);circle(320,527,3.1,C.ink);
    smallCard(320,787,210,234,'JOY');
    gift(500,850,105,110,C.sage);
    fireplace(1080,850,740,420,progress(.12,1.05));
    ornament(1650,355,178,49,1);
    tracked('A LITTLE NOEL',1650,624,11,1.8,C.muted,true);
    gift(1640,850,142,166,C.red);
  }else{
    text('Home for Christmas.',960,211,68,C.ink,1450,'center',600);
    tracked('SMALL DETAILS. WONDERFUL MOMENTS.',960,260,14,3.1,C.muted,true);
    wallWindow(240,349,300,220);chair(390,850,1);
    fireplace(960,850,540,335,1);clock(960,385,58);tree(1560,850,.83);
    gift(609,850,70,100,C.red);gift(1315,850,70,106,C.sage);
    ornament(615,338,228,29,2.4);
    tracked('MERRY CHRISTMAS',960,946,14,3.6,C.ink,true);
  }
  ribbonWipe('#eee1cd','#a57c83');
  ctx.restore();

}
draw.duration = 25;
draw.fps = 60;
draw.bitrate = 100000000;
draw.renderSettings = Object.freeze({
  duration: 25, sceneCount: 3, width: 3840, height: 2160,
  fps: 60, videoBitrate: 100000000, minimumVideoBitrate: 100000000,
  seamlessLoop: true
});

/**
 * CONCEPT 03 - Ornament Symphony / A Curated Christmas Collection
 * Duration: 25 seconds. Three equal scenes. Seamless 16:9 Canvas animation.
 * 3840 x 2160, 60 fps; also scales proportionally to FHD and 2K.
 * Asset-free, original 2D vector drawing. No humans, animals or 3D objects.
 * Static gradient backgrounds. No glow, bloom, shadows or external dependencies.
 * Time is supplied in SECONDS. Load each concept separately.
 * Video export target/minimum: 100,000,000 bits per second (100 Mbps).
 * Canvas draws frames only: the host encoder must enforce the export bitrate.
 */
function draw(ctx, time, width, height) {

